-- Seed: rodada 360 do IEE (2026.2)
--
-- A pesquisa já tinha sido aplicada uma vez, numa ferramenta separada
-- (github.com/sigalestalita/grou-360). As três perguntas, os rótulos da escala
-- e a mecânica "todos avaliam todos, mais autoavaliação" vieram de lá sem
-- alteração de texto; o que muda é que agora rodam dentro do Atlas.
--
-- A diretoria é outra: nenhum dos sete nomes da rodada anterior participa.
--
-- Criada como RASCUNHO de propósito. Colocar no ar é um clique na tela de
-- Pesquisa, e é o que faz os links começarem a valer — quem decide a hora
-- disso é quem conduz, não uma migração.
--
-- Idempotente: rodar de novo não duplica nada.

-- ── Empresa ─────────────────────────────────────────────────────────────────
-- O logo vem do repositório antigo, embutido como data URI porque o SVG é a
-- única peça de marca que o IEE tem lá. As cores saem do próprio símbolo, que é
-- monocromático — dá para trocar em Empresas › Editar quando houver paleta.
INSERT INTO public.companies (id, name, slug, logo_url, primary_color, secondary_color)
VALUES (
  'e1e00000-0000-4000-8000-000000000001'::uuid,
  'IEE — Instituto de Estudos Empresariais',
  'iee',
  'data:image/svg+xml;base64,',
  '#16161A',
  '#040006'
)
ON CONFLICT (id) DO UPDATE
  SET name = EXCLUDED.name,
      logo_url = EXCLUDED.logo_url,
      primary_color = EXCLUDED.primary_color,
      secondary_color = EXCLUDED.secondary_color;

-- ── Pesquisa ────────────────────────────────────────────────────────────────
-- `identified` é verdadeiro: esta rodada, por decisão de quem conduz, registra
-- quem escreveu cada avaliação. A tela avisa o respondente disso antes de ele
-- escrever — ver a nota na coluna `surveys.identified`.
INSERT INTO public.surveys (
  id, company_id, title, description, intro_text, status,
  scale_min, scale_max, scale_labels, is_template, open_access,
  survey_mode, identified, wave_label
)
VALUES (
  'e1e00000-0000-4000-8000-000000000002'::uuid,
  'e1e00000-0000-4000-8000-000000000001'::uuid,
  'Avaliação 360 — Diretoria IEE',
  'Avaliação de desempenho entre os membros da diretoria, com autoavaliação.',
  'Cada pessoa da diretoria avalia todos os colegas e também a si mesma. São três perguntas por avaliação: uma nota e dois campos abertos. Reserve cerca de 15 minutos e responda de uma vez — dá para parar e voltar, mas o texto rende mais num fôlego só.',
  'draft',
  1, 5,
  '["Não atende","Atende minimamente","Atende parcialmente","Atende plenamente","Supera o esperado"]'::jsonb,
  false, false,
  '360', true, '2026.2'
)
ON CONFLICT (id) DO UPDATE
  SET title = EXCLUDED.title,
      description = EXCLUDED.description,
      intro_text = EXCLUDED.intro_text,
      scale_labels = EXCLUDED.scale_labels,
      survey_mode = EXCLUDED.survey_mode,
      identified = EXCLUDED.identified,
      wave_label = EXCLUDED.wave_label;

-- ── Seções ──────────────────────────────────────────────────────────────────
-- `leadership` se repete uma vez por colega avaliado; `self` aparece só na
-- etapa da autoavaliação, e é por isso que as duas existem separadas: o
-- enunciado muda de pessoa ("os talentos de Fulano" vira "as suas fortalezas").
INSERT INTO public.survey_sections (id, survey_id, title, sort_order, section_type)
VALUES
  ('e1e00000-0000-4000-8000-000000000003'::uuid, 'e1e00000-0000-4000-8000-000000000002'::uuid, 'Avaliação da diretoria', 0, 'leadership'),
  ('e1e00000-0000-4000-8000-000000000004'::uuid, 'e1e00000-0000-4000-8000-000000000002'::uuid, 'Autoavaliação',          1, 'self')
ON CONFLICT (id) DO UPDATE
  SET title = EXCLUDED.title, section_type = EXCLUDED.section_type, sort_order = EXCLUDED.sort_order;

