-- ── Matriz: todos avaliam todos, inclusive a si mesmos ──────────────────────
-- Sete pessoas × sete avaliados = 49 etapas no total, sete por pessoa.
INSERT INTO public.evaluation_assignments
  (survey_id, company_id, evaluator_name, evaluatee_name, evaluatee_role, is_self)
SELECT
  'e1e00000-0000-4000-8000-000000000002'::uuid,
  'e1e00000-0000-4000-8000-000000000001'::uuid,
  avaliador.name,
  avaliado.name,
  avaliado.department,
  avaliador.id = avaliado.id
FROM public.respondents avaliador
CROSS JOIN public.respondents avaliado
WHERE avaliador.survey_id = 'e1e00000-0000-4000-8000-000000000002'::uuid
  AND avaliado.survey_id  = 'e1e00000-0000-4000-8000-000000000002'::uuid
ON CONFLICT (survey_id, evaluator_name, evaluatee_name) DO UPDATE
  SET evaluatee_role = EXCLUDED.evaluatee_role, is_self = EXCLUDED.is_self;
